const fs=require("fs");
const path=require("path");
const root="/tmp/logic-extract";
const needle=Buffer.from("RepoAuth");
function walk(d){
  for(const e of fs.readdirSync(d,{withFileTypes:true})){
    const p=path.join(d,e.name);
    if(e.isDirectory()) walk(p);
    else if(e.name.endsWith(".class")){
      const buf=fs.readFileSync(p);
      if(buf.includes(needle) && !p.endsWith("RepoAuthKt.class")){
        console.log("REF: "+p.replace(root,""));
      }
    }
  }
}
walk(root);
console.log("done");
EOF
